"""Registry of the converters that turn a source into reading HTML.

Deliberately free of PyMuPDF imports: `Source.is_converted` is read on every
serialisation of a source list, and pulling the extraction stack into the model
layer for a single integer would make listing a studyspace pay for it.
"""

REFLOW = "reflow"
LAYOUT = "layout"

CONVERTER_CHOICES = (
    (REFLOW, "Reflowable text"),
    (LAYOUT, "Faithful page layout"),
)

# Bump the entry of a converter whenever a change to it would produce different
# output for the same input. Stored HTML generated by an older version is
# regenerated on the next read.
CONVERTER_VERSIONS = {
    REFLOW: 3,
    LAYOUT: 2,
}

DEFAULT_CONVERTER = REFLOW


def version_of(mode: str) -> int:
    """Current version of a converter, or 0 for one that no longer exists.

    Returning 0 rather than raising is what retires a converter safely: sources
    still marked with it never match, so they are simply reconverted.
    """
    return CONVERTER_VERSIONS.get(mode, 0)


def is_known(mode: str) -> bool:
    return mode in CONVERTER_VERSIONS
